// Overwrite policy: per-file write decision using three-way merge against a
// canonical snapshot kept under `.metaobjects/.gen-state/`.
//
// Replaces the rc.11 marker-based clobber-or-refuse policy (strategy (a) from
// spike 002) with strategy (b) — git-merge-file-driven three-way merge. The
// `@generated` marker becomes purely informational (templates may still emit
// it for human readers); the policy no longer consults it.
//
// Per-file flow:
//
//   1. Render fresh content to a tmpfile.
//   2. If the output doesn't exist → write + copy to .gen-state/.
//   3. If .gen-state/<relPath> exists → run `git merge-file --diff3` against
//      (current, .gen-state snapshot, fresh tmpfile). Exit 0 → clean merge,
//      advance .gen-state to fresh content. Exit > 0 → leave conflict markers
//      in the output file, do NOT advance .gen-state; status "conflict".
//   4. If the .gen-state BODY is absent but the file exists, consult the
//      committed hash manifest: identical fresh content → "unchanged"; the file
//      still hashes to what we recorded writing → safe to overwrite; anything
//      else (edited, or no record at all) → "refused", naming the file. The
//      `baseline: "fresh"` flag opts into "overwrite from fresh and re-baseline".
//
// Integrity (caveat 2 from the spike): we keep a sha-256 of each canonical
// snapshot, in the manifest under `.gen-state/.hashes/` (one file per model package).
//
// THE MANIFEST IS COMMITTED; THE BODIES ARE NOT. That split is what makes step 4
// possible. A hash per path is small and reviewable, where a second full copy of
// all generated output is neither — and a hash is already sufficient to tell
// "nobody touched this" from "somebody edited this", which is the only thing
// steps 4 and the orphan-delete path need to know. The cost, stated: without a
// body there is no base to merge against, so a diverged file on a fresh clone is
// REFUSED rather than merged. That is a smaller loss than it sounds, because the
// behaviour it replaces was a silent overwrite.

import {
  existsSync,
  readFileSync,
  writeFileSync,
  mkdirSync,
  copyFileSync,
  rmSync,
} from "node:fs";
import { dirname, join, isAbsolute, relative, resolve } from "node:path";
import { spawnSync } from "node:child_process";
import {
  HASHES_DIR,
  LEGACY_HASHES_FILE,
  ROOT_MANIFEST,
  buildPlacementIndex,
  manifestExists,
  manifestFileName,
  placeEntry,
  readManifestState,
  type ManifestState,
  type PlacementIndex,
  type PlacementObject,
} from "./hash-manifest-store.js";
import { tmpdir } from "node:os";
import { createHash, randomBytes } from "node:crypto";

/**
 * Every outcome a write decision can have. An `as const` array rather than a bare
 * union so a consumer that MAPS these — the CLI's reporting layer does — can be
 * gated against the full set instead of against a second list of its own. The CLI
 * silently folded "overwrite" into "new" for exactly as long as no test could
 * enumerate what it was folding.
 */
export const WRITE_STATUSES = [
  "new",
  "unchanged",
  "overwrite",
  "merged",
  "conflict",
  "refused",
  "skipped",
  /** `--baseline=adopt` — the file WOULD have been refused, and instead its current
   *  content was recorded as the merge base. Nothing was written. Its own status
   *  rather than "unchanged" or "skipped" because the run's whole product is the
   *  manifest it just created: a summary that reported these as unchanged would
   *  hide the one thing the adopter has to commit. */
  "adopted",
  /** FR-038 §8 — deleted because it was generated by a previous run, is no longer
   *  generated, and was never edited by hand. Reported as a file outcome rather
   *  than a warning because a deletion is exactly as consequential as a write,
   *  and a run summary that lists writes but hides deletions is how a silent
   *  deletion happens. */
  "removed",
] as const;

export type WriteStatus = (typeof WRITE_STATUSES)[number];

/**
 * "overwrite" — default; three-way merge if .gen-state exists, else write-if-
 *   different / first-time-existing flow.
 * "skip-existing" — never write over an existing file; status "skipped".
 *   Useful for `meta gen --dry-run` style flows.
 */
export type MergeStrategy = "overwrite" | "skip-existing";

/** "default" — the standard three-way merge flow described in the file header.
 *  "fresh" — opt-in via `meta gen --baseline=fresh`. When .gen-state is absent
 *  but the file exists, OVERWRITE with fresh content and seed .gen-state from
 *  the fresh content (caveat 3 escape hatch).
 *  "adopt" — opt-in via `meta gen --baseline=adopt`. Same population, opposite
 *  half: where the run would REFUSE, record the file's CURRENT content as the
 *  merge base and write nothing. It exists because the refusal's leading remedy
 *  ("commit .hashes/") could not be performed by the population it named —
 *  nothing writes a manifest until a gen succeeds, and gen refuses until one
 *  exists. `adopt` is the run that produces the file to commit.
 *
 *  What it is NOT: protection for an edit already inside one of those files. The
 *  base becomes the edited text, so base == ours and the next regen's three-way
 *  merge takes fresh output wholesale. It protects edits made FROM THEN ON, and
 *  it guarantees that establishing the baseline writes nothing — which is what
 *  lets the content change land as its own reviewable diff afterwards. */
export type BaselineMode = "default" | "fresh" | "adopt";

export interface DecideAndWriteOpts {
  strategy?: MergeStrategy;
  /** Absolute path to the .gen-state/ root for this project. When undefined,
   *  we fall back to a process-isolated tmpdir — fine for tests but the CLI
   *  always supplies the real project value via runGen(). */
  genStateDir?: string;
  /** Path the snapshot is keyed by — usually the path relative to the
   *  project root, but ANY stable identifier works. When undefined, derived
   *  from `path` (so unit tests can call without supplying it). */
  outputRelPath?: string;
  /** First-time-existing-file behavior. */
  baseline?: BaselineMode;
  /**
   * What a hand edit to a file `gen` recorded writing gets: `"keep"` (the default) merges
   * it or refuses the file; `"overwrite"` replaces the file with fresh output and
   * re-baselines its record, reporting `discardedEdit` so the caller can name it. A file
   * with no record of being generated is never overwritten by this setting.
   */
  handEdits?: HandEdits;
}

/**
 * The per-generator hand-edit setting (`Generator.handEdits`), the same name and values in
 * every port. `"keep"`, the default, protects an edit to a generated file (merged, or the
 * file refused by name); `"overwrite"` discards it: the file is regenerated and its record
 * re-baselined, and an edited file no generator emits any more is deleted.
 */
export type HandEdits = "keep" | "overwrite";

export interface WriteResult {
  path: string;
  status: WriteStatus;
  /** Present when status is "conflict" or "refused" — human-readable reason,
   *  naming what the user must do. A refusal nobody can act on gets the file
   *  deleted by hand, which is the outcome refusing exists to prevent. */
  conflictHint?: string;
  /** True when a hand edit was replaced with fresh output under `handEdits: "overwrite"`. */
  discardedEdit?: boolean;
}

type HashesFile = Record<string, string>;

function sha256(content: string | Buffer): string {
  return createHash("sha256").update(content).digest("hex");
}

/**
 * The manifest of a run in progress, held in memory and written once at its end.
 *
 * Every write updates the manifest, and the manifest is the whole project's record, so
 * rewriting it per written file made bookkeeping quadratic in the project's size: at
 * a thousand generated files the rewrites were most of a run's wall time, for the same
 * bytes one write at the end produces. `withManifestBatch` holds the manifest for one
 * gen-state directory in memory while it runs; every reader and writer in this module
 * goes through it, so a read inside the batch sees the batch's own writes.
 *
 * Synchronous on purpose: nothing can interleave with a batch, so two runs in one
 * process cannot see each other's half-finished manifest.
 */
interface ManifestBatch {
  raw: Record<string, unknown>;
  dirty: boolean;
  /** Where each entry was read from, so a write rewrites only the files that changed. */
  state: ManifestState;
  /** The run's model, for placing entries that carry no `sourceNode`. */
  index: PlacementIndex | undefined;
}
const manifestBatches = new Map<string, ManifestBatch>();

function manifestBatchOpen(genStateDir: string): boolean {
  return batchFor(genStateDir) !== undefined;
}

function batchFor(genStateDir: string): ManifestBatch | undefined {
  return manifestBatches.size === 0 ? undefined : manifestBatches.get(resolve(genStateDir));
}

/**
 * Run `fn` with the manifest under `genStateDir` held in memory, and write it once when
 * `fn` returns or throws, only if something changed. A throw still writes what was
 * recorded before it: those files are on disk, and a manifest that forgot them would
 * read them as unrecorded and refuse them next run. When `fn` threw, a failed manifest
 * write is swallowed so `fn`'s error stays the one reported. A nested call for the same
 * directory joins the outer batch.
 *
 * `objects` is the run's loaded model (root-level object names and packages): the manifest
 * is one file per package, and an entry that records no `sourceNode` is filed under the
 * package of the object its file is named for. A run that finds the legacy single
 * `.hashes.json` writes even when nothing else changed, because that is the migration.
 */
export function withManifestBatch<T>(
  genStateDir: string,
  fn: () => T,
  objects?: readonly PlacementObject[],
): T {
  const key = resolve(genStateDir);
  if (manifestBatches.has(key)) return fn();
  const state = readManifestState(genStateDir);
  const batch: ManifestBatch = {
    raw: state.entries,
    dirty: state.legacy,
    state,
    index: objects !== undefined ? buildPlacementIndex(objects) : undefined,
  };
  manifestBatches.set(key, batch);
  let result: T;
  try {
    result = fn();
  } catch (err) {
    manifestBatches.delete(key);
    try {
      if (batch.dirty) flushBatch(genStateDir, batch);
    } catch {
      // `fn`'s error is the cause to report; a failed manifest write must not replace it.
    }
    throw err;
  }
  manifestBatches.delete(key);
  if (batch.dirty) flushBatch(genStateDir, batch);
  return result;
}

function flushBatch(genStateDir: string, batch: ManifestBatch): void {
  writeManifestFiles(genStateDir, batch.raw, batch.state, batch.index);
}

function manifestText(entries: Record<string, unknown>): string {
  // Keys SORTED, because this file is committed: insertion order would make the diff
  // depend on which entity happened to generate first.
  const sorted: Record<string, unknown> = {};
  for (const key of Object.keys(entries).sort()) sorted[key] = entries[key];
  return JSON.stringify(sorted, null, 2) + "\n";
}

const NEGATION_LEGACY = "!.gen-state/.hashes.json";
const NEGATION_DIR = "!.gen-state/.hashes/";

/**
 * The scaffolded `.metaobjects/.gitignore` ignores `.gen-state/*` and un-ignores the legacy
 * file only, so the new directory would be ignored and never reach another machine. Put its
 * negation where the legacy one was and drop the legacy one, which names a file that no longer
 * exists; with no legacy line, add it after the `.gen-state/*` rule. A file with no such rule
 * is left alone. Only the migration calls this.
 */
export function ensureHashesDirNotIgnored(genStateDir: string): void {
  const file = join(dirname(genStateDir), ".gitignore");
  let text: string;
  try {
    text = readFileSync(file, "utf-8");
  } catch {
    return;
  }
  const lines = text.split("\n");
  if (!lines.some((l) => l.trim() === ".gen-state/*")) return;
  const hasDir = lines.some((l) => l.trim() === NEGATION_DIR);
  const firstLegacy = lines.findIndex((l) => l.trim() === NEGATION_LEGACY);
  const out: string[] = [];
  let placed = hasDir;
  lines.forEach((line, i) => {
    const t = line.trim();
    if (t === NEGATION_LEGACY) {
      if (i === firstLegacy && !placed) {
        out.push(NEGATION_DIR);
        placed = true;
      }
      return;
    }
    out.push(line);
    if (!placed && firstLegacy === -1 && t === ".gen-state/*") {
      out.push(NEGATION_DIR);
      placed = true;
    }
  });
  const next = out.join("\n");
  if (next !== text) writeFileSync(file, next);
}

/**
 * Write `entries` as per-package manifests. Writes only the files whose bytes changed,
 * removes package files that no longer hold an entry, and removes the legacy file (the
 * migration). Returns nothing: a caller that wanted "did anything change" asked before.
 */
export function writeManifestFiles(
  genStateDir: string,
  entries: Record<string, unknown>,
  state: ManifestState,
  index: PlacementIndex | undefined,
): void {
  const groups = new Map<string, Record<string, unknown>>();
  for (const [path, entry] of Object.entries(entries)) {
    const pkg = placeEntry(path, entry, index);
    const name = pkg === undefined ? (state.fileOf.get(path) ?? ROOT_MANIFEST) : manifestFileName(pkg);
    let group = groups.get(name);
    if (group === undefined) groups.set(name, (group = {}));
    group[path] = entry;
  }
  // "No manifest" must stay distinguishable from "an empty one".
  if (groups.size === 0) groups.set(ROOT_MANIFEST, {});

  const dir = join(genStateDir, HASHES_DIR);
  mkdirSync(dir, { recursive: true });
  for (const [name, group] of groups) {
    const text = manifestText(group);
    if (state.texts.get(name) === text) continue;
    writeFileSync(join(dir, name), text);
    state.texts.set(name, text);
  }
  for (const name of [...state.texts.keys()]) {
    if (groups.has(name)) continue;
    rmSync(join(dir, name), { force: true });
    state.texts.delete(name);
  }
  state.fileOf = new Map();
  for (const [name, group] of groups) for (const path of Object.keys(group)) state.fileOf.set(path, name);

  if (state.legacy) {
    rmSync(join(genStateDir, LEGACY_HASHES_FILE), { force: true });
    state.legacy = false;
    ensureHashesDirNotIgnored(genStateDir);
  }
}

function readRawManifest(genStateDir: string): Record<string, unknown> {
  const batch = batchFor(genStateDir);
  return batch !== undefined ? batch.raw : readManifestState(genStateDir).entries;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function entryHash(value: unknown): string | undefined {
  if (typeof value === "string") return value;
  if (isRecord(value) && typeof value.hash === "string") return value.hash;
  return undefined;
}

function loadHashes(genStateDir: string): HashesFile {
  const hashes: HashesFile = {};
  for (const [key, value] of Object.entries(readRawManifest(genStateDir))) {
    const hash = entryHash(value);
    if (hash !== undefined) hashes[key] = hash;
  }
  return hashes;
}

function saveHashes(genStateDir: string, hashes: HashesFile): void {
  const raw = readRawManifest(genStateDir);
  const next: Record<string, unknown> = {};
  for (const [key, hash] of Object.entries(hashes)) {
    const existing = raw[key];
    next[key] = isRecord(existing) ? { ...existing, hash } : hash;
  }
  // A run that changed nothing writes nothing (ADR-0064 §1): the manifest is only written
  // when an entry was added, changed or removed.
  if (manifestExists(genStateDir) || manifestBatchOpen(genStateDir)) {
    const same =
      Object.keys(next).length === Object.keys(raw).length &&
      Object.keys(next).every((k) => JSON.stringify(next[k]) === JSON.stringify(raw[k]));
    if (same) return;
  }
  writeRawManifest(genStateDir, next);
}

/** Record one path's hash, keeping any other fields on its entry. */
function setHash(genStateDir: string, relPath: string, hash: string): void {
  const raw = readRawManifest(genStateDir);
  const existing = raw[relPath];
  if (entryHash(existing) === hash) return;
  raw[relPath] = isRecord(existing) ? { ...existing, hash } : hash;
  writeRawManifest(genStateDir, raw);
}

function writeRawManifest(genStateDir: string, entries: Record<string, unknown>): void {
  const batch = batchFor(genStateDir);
  if (batch !== undefined) {
    batch.raw = entries;
    batch.dirty = true;
    return;
  }
  // Outside a batch: read what is there (for the files' current bytes), then write.
  writeManifestFiles(genStateDir, entries, readManifestState(genStateDir), undefined);
}

/** What produced one generated file: the generator, and the metadata node it was rendered
 *  from when it was rendered from one. */
export interface GeneratedProvenance {
  generatedBy: string;
  /** The resolution key of the node (`acme::shop::Order`). Absent for a file rendered from
   *  the whole model or a whole package — a barrel, a docs index. */
  sourceNode?: string;
}

/** The manifest fields provenance owns. Every other field on an entry — `hash`, and the
 *  JVM's `generator` / `outputDir` owner (ADR-0060) — is kept as it is. */
const PROVENANCE_FIELDS = ["generatedBy", "sourceNode"] as const;

/**
 * Record, on each recorded path's manifest entry, the node it was generated from.
 *
 * A path with a source node becomes `{ "hash", "generatedBy", "sourceNode" }`; one without
 * keeps (or returns to) the plain `"<hash>"` form, so a file rendered from the whole model
 * adds nothing to the committed manifest. A path with no recorded hash is left alone — this
 * describes what a write recorded, it never records a write.
 *
 * `generatedBy` is deliberately not the JVM's `generator` field: there `generator` is an
 * OWNERSHIP claim the orphan sweep acts on, and a TypeScript name in it would read as a
 * generator no Maven execution configures.
 *
 * Batched: one read and at most one write for the whole run. Nothing is written when no
 * entry changes, so a regeneration that changes nothing leaves the file's bytes alone.
 */
export function recordGeneratedProvenance(
  genStateDir: string,
  provenance: ReadonlyMap<string, GeneratedProvenance>,
): void {
  if (!hasHashManifest(genStateDir)) return;
  const raw = readRawManifest(genStateDir);
  let changed = false;
  for (const [key, prov] of provenance) {
    const existing = raw[key];
    const hash = entryHash(existing);
    if (hash === undefined) continue;
    const rest: Record<string, unknown> = {};
    if (isRecord(existing)) {
      for (const [k, v] of Object.entries(existing)) {
        if (k !== "hash" && !(PROVENANCE_FIELDS as readonly string[]).includes(k)) rest[k] = v;
      }
    }
    const next: unknown = prov.sourceNode !== undefined
      ? { hash, ...rest, generatedBy: prov.generatedBy, sourceNode: prov.sourceNode }
      : Object.keys(rest).length > 0 ? { hash, ...rest } : hash;
    if (JSON.stringify(next) !== JSON.stringify(existing)) {
      raw[key] = next;
      changed = true;
    }
  }
  if (changed) writeRawManifest(genStateDir, raw);
}

/**
 * Every recorded path that carries provenance, as `recordGeneratedProvenance` wrote it: the
 * generator, and the source node when there is one. A plain `"<hash>"` entry carries no
 * generator and is left out. Sorted by path.
 */
export function listGeneratedProvenance(
  genStateDir: string,
): { path: string; generatedBy: string; sourceNode?: string }[] {
  const out: { path: string; generatedBy: string; sourceNode?: string }[] = [];
  for (const [path, entry] of Object.entries(readRawManifest(genStateDir))) {
    if (!isRecord(entry) || typeof entry.generatedBy !== "string") continue;
    out.push({
      path,
      generatedBy: entry.generatedBy,
      ...(typeof entry.sourceNode === "string" && { sourceNode: entry.sourceNode }),
    });
  }
  return out.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
}

// ---------------------------------------------------------------------------
// FR-038 §8 — readers for orphan reconciliation.
//
// The manifest's key set is the ONLY record of what a previous run wrote, so
// it is also the only way to notice that a file we used to generate is no longer
// generated. These three functions expose that record without widening the write
// path: nothing here decides anything (see reconcile-orphans.ts) and nothing here
// touches an output file (see orphan-sweep.ts).
// ---------------------------------------------------------------------------

/**
 * Every snapshot key recorded under `genStateDir` — in a runner-driven project,
 * the project-relative path of every file some previous `meta gen` wrote.
 *
 * Empty for a gen-state directory that does not exist yet, which is what makes a
 * first run, an ephemeral test run and `verify --codegen`'s throwaway root all
 * reconcile nothing.
 */
export function listGeneratedPaths(genStateDir: string): string[] {
  return Object.keys(loadHashes(genStateDir));
}

/**
 * sha-256 of `content`, hex — the same function that produces the manifest's hashes.
 *
 * Exported so a caller can ask the one question the manifest exists to answer
 * ("is this file byte-for-byte what we recorded writing?") without needing the
 * snapshot body, which is what makes the answer available on a fresh clone.
 */
export function contentHash(content: string): string {
  return sha256(content);
}

/**
 * The hash we recorded when we last wrote `relPath`, or undefined if we have no
 * record of ever writing it.
 *
 * This is the COMMITTED half of `.gen-state`. The snapshot bodies stay ignored —
 * they are a second full copy of all generated output — but a hash per path is
 * small enough to commit and review, and it is sufficient to distinguish "nobody
 * touched this" from "somebody edited this", which is the only distinction the
 * overwrite and delete decisions actually need.
 */
export function readGeneratedHash(
  genStateDir: string,
  relPath: string,
): string | undefined {
  return entryHash(readRawManifest(genStateDir)[relPath]);
}

/**
 * True when the file at `relPath` is byte-for-byte what we recorded writing.
 *
 * FAILS CLOSED: with no recorded hash we cannot prove anything, so the answer is
 * false. Both the write path and the orphan-delete path ask this one question of
 * this one piece of evidence — before this existed they answered the same
 * uncertainty in opposite directions inside a single feature, refusing to DELETE
 * a hand-edited file while silently OVERWRITING one.
 */
export function isPristineGenerated(
  genStateDir: string,
  relPath: string,
  current: string,
): boolean {
  const recorded = readGeneratedHash(genStateDir, relPath);
  return recorded !== undefined && recorded === sha256(current);
}

/**
 * The snapshot of what we last wrote to `relPath`, or undefined when there is no
 * trustworthy one.
 *
 * HASH-CHECKED on purpose. A caller comparing this against the file on disk is
 * asking "is the output still exactly what I wrote?" — and a snapshot that fails
 * its own hash cannot answer that. Returning the stale text would let a
 * reconciling caller conclude "untouched" and delete a file it cannot vouch for,
 * so a tampered snapshot reads as absent and the caller fails closed.
 */
export function readGeneratedSnapshot(
  genStateDir: string,
  relPath: string,
): string | undefined {
  return readSnapshotChecked(genStateDir, relPath)?.text;
}

/**
 * Drop both halves of the record for paths this run no longer generates — each
 * snapshot file and its manifest entry.
 *
 * BOTH halves, or the next run sees the path again in `listGeneratedPaths` and
 * re-decides an orphan that has already been dealt with. A no-op for a path that was
 * never generated.
 *
 * Batched deliberately: one manifest read and one write for the whole set. A per-path
 * variant re-reads, re-sorts and rewrites the entire manifest every call, so clearing k
 * orphans rewrote it k times — on a project with hundreds of generated files that makes
 * bookkeeping the dominant cost of `meta gen`, for an identical result.
 */
export function forgetGeneratedPaths(
  genStateDir: string,
  relPaths: Iterable<string>,
): void {
  const hashes = loadHashes(genStateDir);
  let changed = false;
  for (const relPath of relPaths) {
    const snapshot = snapshotPath(genStateDir, relPath);
    if (existsSync(snapshot)) rmSync(snapshot, { force: true });
    if (relPath in hashes) {
      delete hashes[relPath];
      changed = true;
    }
  }
  if (changed) saveHashes(genStateDir, hashes);
}

const ENGINE_FILE = ".engine.json";

/**
 * The codegen engine version that last wrote this `.gen-state`, or undefined if it
 * was never stamped (a pre-#232 snapshot, or a fresh project). Informational only —
 * a separate reserved file from the hash manifest, it never participates in the
 * three-way merge decision. (#232)
 */
export function loadEngineVersion(genStateDir: string): string | undefined {
  const f = join(genStateDir, ENGINE_FILE);
  if (!existsSync(f)) return undefined;
  try {
    const parsed: unknown = JSON.parse(readFileSync(f, "utf-8"));
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      const v = (parsed as { codegenVersion?: unknown }).codegenVersion;
      return typeof v === "string" ? v : undefined;
    }
  } catch {
    // Malformed → treat as unstamped; the stamp is informational, never load-bearing.
  }
  return undefined;
}

/** Record the codegen engine version alongside the gen-state hashes (#232). */
export function saveEngineVersion(genStateDir: string, version: string): void {
  // A run that changed nothing writes nothing (ADR-0064 §1), tool state included.
  if (loadEngineVersion(genStateDir) === version) return;
  mkdirSync(genStateDir, { recursive: true });
  writeFileSync(
    join(genStateDir, ENGINE_FILE),
    JSON.stringify({ codegenVersion: version }, null, 2) + "\n",
  );
}

function snapshotPath(genStateDir: string, relPath: string): string {
  // `.hashes/` (and the legacy `.hashes.json`) is reserved at the top of .gen-state/; relPath must never
  // collide with it. Output paths derived from entity names ("Post.ts" etc.)
  // are JS-identifier-shape so this is a non-issue in practice.
  return join(genStateDir, relPath);
}

/** Synchronously copy `src` content into the snapshot at `<genStateDir>/<relPath>`
 *  and refresh the hash for `relPath`. */
function advanceSnapshot(
  genStateDir: string,
  relPath: string,
  content: string,
): void {
  const dest = snapshotPath(genStateDir, relPath);
  // The body is a local cache; rewriting one that already holds these bytes only moves its
  // timestamp.
  if (!existsSync(dest) || readFileSync(dest, "utf-8") !== content) {
    mkdirSync(dirname(dest), { recursive: true });
    writeFileSync(dest, content);
  }
  setHash(genStateDir, relPath, sha256(content));
}

/** Return the snapshot text iff present AND the hash matches; else undefined. */
function readSnapshotChecked(
  genStateDir: string,
  relPath: string,
): { text: string } | undefined {
  const path = snapshotPath(genStateDir, relPath);
  if (!existsSync(path)) return undefined;
  const text = readFileSync(path, "utf-8");
  const expected = readGeneratedHash(genStateDir, relPath);
  if (expected !== undefined && expected !== sha256(text)) {
    return undefined;
  }
  return { text };
}

/** Thrown when git is unavailable. Surfaces as a clear CLI error rather than
 *  a generic ENOENT halfway through a regen. */
export class GitMissingError extends Error {
  constructor() {
    super(
      "meta gen: `git` binary not found on PATH. Three-way-merge regen " +
        "requires git (any modern version). Install git and re-run.",
    );
    this.name = "GitMissingError";
  }
}

interface MergeOutcome {
  /** 0 → clean merge; > 0 → conflicts present (file contains diff3 markers). */
  exitCode: number;
  /** stderr text — surfaced on unexpected errors. */
  stderr: string;
  /** Resulting file contents on disk after the merge (always read; clean or
   *  conflicting). */
  mergedContent: string;
}

/** Run `git merge-file --diff3 -L<...> <out> <base> <fresh>`. The output is
 *  written in-place into `outPath`. Returns the exit code (0 = clean, > 0 =
 *  conflicts) and the resulting file contents.
 *
 *  The git binary is "git" by default; set `META_GEN_GIT` in the environment
 *  to a different path (useful for tests that simulate "git not installed"). */
function runGitMergeFile(
  outPath: string,
  basePath: string,
  freshPath: string,
): MergeOutcome {
  const gitBin = process.env.META_GEN_GIT ?? "git";
  let res;
  try {
    res = spawnSync(
      gitBin,
      [
        "merge-file",
        "--diff3",
        "-L",
        "your edits",
        "-L",
        "last generated",
        "-L",
        "fresh from meta gen",
        outPath,
        basePath,
        freshPath,
      ],
      { encoding: "utf-8" },
    );
  } catch (err) {
    const msg = (err as Error).message ?? "";
    if (msg.includes("ENOENT")) throw new GitMissingError();
    throw err;
  }
  if (res.error) {
    const code = (res.error as NodeJS.ErrnoException).code;
    if (code === "ENOENT") throw new GitMissingError();
    throw res.error;
  }
  // `git merge-file` returns the conflict count (0 = clean, > 0 = conflicts,
  // < 0 = error). Negative is unexpected — surface verbatim.
  const exitCode = res.status ?? 0;
  if (exitCode < 0) {
    throw new Error(
      `git merge-file failed for ${outPath}: ${res.stderr || res.stdout}`,
    );
  }
  const mergedContent = readFileSync(outPath, "utf-8");
  return { exitCode, stderr: res.stderr ?? "", mergedContent };
}

/** The directory merge temporaries go in: `$DEV_SCRATCH` when set, else the OS temp dir.
 *  Exported for the test that a run leaves nothing behind there. */
export function mergeTempDir(): string {
  const scratch = process.env.DEV_SCRATCH;
  return join(scratch !== undefined && scratch !== "" ? scratch : tmpdir(), "meta-gen-merge");
}

/** Write `content` to a freshly-named temp file in `mergeTempDir()`; return the path. The
 *  caller deletes it in a `finally`. */
function writeTmpfile(content: string): string {
  const dir = mergeTempDir();
  mkdirSync(dir, { recursive: true });
  const path = join(dir, `${Date.now()}-${randomBytes(6).toString("hex")}.tmp`);
  writeFileSync(path, content);
  return path;
}

/** Resolve the snapshot key for a given output path. Falls back to a stable
 *  hash-of-path so unit tests that pass arbitrary tmpdir outputs still get a
 *  consistent .gen-state key. */
function defaultOutputRelPath(outputPath: string): string {
  // Use sha256 of the absolute path → hex; lets tests work without supplying
  // an explicit relPath. NOT used by the runner — runGen always passes the
  // real project-relative path.
  return sha256(resolve(outputPath)).slice(0, 32);
}

/** Where this call's gen-state lives. Shared by the write path and the preview so
 *  the two cannot resolve it differently — a preview that consults a different
 *  manifest than the write would be the same disagreement-between-two-answers bug
 *  this whole change exists to remove. */
function resolveGenStateDir(opts: DecideAndWriteOpts): string {
  if (opts.genStateDir === undefined) return join(tmpdir(), "meta-gen-state-fallback");
  return isAbsolute(opts.genStateDir) ? opts.genStateDir : resolve(opts.genStateDir);
}

/** True when this project has a hash manifest at all — as opposed to a manifest
 *  that simply has no entry for some path.
 *
 *  The distinction drives the upgrade message: a project with NO manifest predates
 *  the manifest being committed, so its refusals are one fixable configuration
 *  problem rather than N independent hand edits, and it deserves one instruction
 *  instead of a wall of per-file warnings. */
export function hasHashManifest(genStateDir: string): boolean {
  if (batchFor(genStateDir)?.dirty === true) return true;
  return manifestExists(genStateDir);
}

/** Normalize the legacy `MergeStrategy` string shorthand into an options object. */
function normalizeOpts(
  optsOrStrategy: DecideAndWriteOpts | MergeStrategy,
): DecideAndWriteOpts {
  return typeof optsOrStrategy === "string" ? { strategy: optsOrStrategy } : optsOrStrategy;
}

/**
 * The single decision tree `decideAndWrite` and `previewWriteStatus` both classify
 * through — the fix for the risk named at the top of this file. Two functions that
 * each re-derive "which case applies" from scratch can drift out of step in their
 * branch ORDER, and when they do, the preview lies. Every branch that decides WHICH
 * case an input falls into lives here, exactly once. `decideAndWrite` executes the
 * case (the write, the merge, the snapshot advance — see its own comments for the
 * "how"); `previewWriteStatus` maps the case straight to a `WriteStatus` with no
 * side effects. Neither function repeats the ordering, so neither can disagree with
 * the other about it.
 */
type WriteCase =
  | { kind: "new" }
  | { kind: "skip" }
  | { kind: "no-snapshot-fresh-unchanged" }
  | { kind: "no-snapshot-fresh-overwrite" }
  | { kind: "hand-edit-overwrite" }
  | { kind: "no-snapshot-unchanged" }
  | { kind: "no-snapshot-pristine-overwrite" }
  | { kind: "no-snapshot-refused"; hasRecord: boolean }
  | { kind: "no-snapshot-adopt"; currentText: string }
  | { kind: "snapshot-unchanged" }
  | { kind: "fresh-equals-disk" }
  | { kind: "snapshot-pristine-overwrite" }
  | { kind: "snapshot-merge-required"; snapshotText: string };

function classifyWrite(
  path: string,
  content: string,
  opts: DecideAndWriteOpts,
): WriteCase {
  // First-time write — file doesn't exist.
  if (!existsSync(path)) return { kind: "new" };

  if ((opts.strategy ?? "overwrite") === "skip-existing") return { kind: "skip" };

  // File exists. Load the canonical snapshot if any.
  const genStateDir = resolveGenStateDir(opts);
  const relPath = opts.outputRelPath ?? defaultOutputRelPath(path);
  const storedSnapshot = readSnapshotChecked(genStateDir, relPath);
  const current = readFileSync(path, "utf-8");

  // A snapshot body is a gitignored local cache, so it outlives a `git checkout` that
  // moves the file to content it never described. `--baseline=fresh` is documented to
  // overwrite a file the committed manifest has NO RECORD of; a stale body for such a path
  // is not a merge base, and merging against it keeps the old content as a "hand edit".
  // Only `fresh`, and only for a path with no recorded hash: every other mode still merges.
  const snapshot =
    storedSnapshot !== undefined &&
    (opts.baseline ?? "default") === "fresh" &&
    readGeneratedHash(genStateDir, relPath) === undefined
      ? undefined
      : storedSnapshot;

  // `handEdits: "overwrite"`: an edit to a file we recorded writing is discarded, not
  // merged or refused. "Recorded" is the committed hash, or a local snapshot body; a file
  // with neither is not ours, and the default rules below still refuse it.
  if (opts.handEdits === "overwrite" && current !== content) {
    const recorded = readGeneratedHash(genStateDir, relPath);
    const edited =
      recorded !== undefined
        ? recorded !== sha256(current)
        : snapshot !== undefined && snapshot.text !== current;
    if (edited) return { kind: "hand-edit-overwrite" };
  }

  // First-time regen on a pre-existing file (no snapshot) — caveat 3. `baseline`
  // only ever applies here: BaselineMode's own doc comment says so ("When
  // .gen-state is absent but the file exists"), and a snapshot body — handled
  // below — always gets the real three-way merge, except the unrecorded-path
  // case of `fresh` just above.
  if (snapshot === undefined) {
    if ((opts.baseline ?? "default") === "fresh") {
      // Opt-in escape hatch: overwrite and seed the snapshot from fresh.
      return current === content
        ? { kind: "no-snapshot-fresh-unchanged" }
        : { kind: "no-snapshot-fresh-overwrite" };
    }

    // No snapshot BODY. That is the normal state, not an edge case: the bodies
    // are gitignored, so every fresh clone and every CI runner arrives here.
    //
    // Previously this branch wrote the fresh content unconditionally, which meant
    // the documented promise that hand edits survive regeneration was false in
    // precisely the situation adopters spend most of their time in — and the CLI
    // labelled the replacement `NEW`.
    //
    // The committed hash manifest answers the only question that matters. Note
    // this is the SAME question, asked of the same evidence, as the orphan-delete
    // path: see `isPristineGenerated`.
    if (current === content) return { kind: "no-snapshot-unchanged" };

    if (isPristineGenerated(genStateDir, relPath, current)) {
      // Byte-for-byte what we last wrote, so replacing it loses nothing. This is
      // the common fresh-clone case (a formatter or engine bump moved the output)
      // and it must not refuse, or a clean checkout would stall on every file.
      return { kind: "no-snapshot-pristine-overwrite" };
    }

    // Either somebody edited it (hash mismatch) or we have no record of writing
    // it at all (no hash). Both are unprovable, so fail closed.
    //
    // …unless the caller has explicitly adopted what is on disk. `adopt` is placed
    // HERE, at the refusal, rather than at the top of the no-snapshot branch, and
    // that placement is the design: it means adopting can only ever convert a
    // refusal into a recorded baseline. Everything else — unchanged, and the
    // pristine-file overwrite a fresh clone depends on — keeps behaving exactly as
    // it does without the flag, so a project cannot accidentally freeze its
    // regeneration by passing it.
    if ((opts.baseline ?? "default") === "adopt") {
      return { kind: "no-snapshot-adopt", currentText: current };
    }

    return {
      kind: "no-snapshot-refused",
      hasRecord: readGeneratedHash(genStateDir, relPath) !== undefined,
    };
  }

  // Snapshot exists — a real three-way merge decides this one.
  // Fast path: nothing changed.
  if (current === content && snapshot.text === content) {
    return { kind: "snapshot-unchanged" };
  }
  // The file already holds exactly the fresh bytes, so a merge could only rewrite it with
  // the same content and move its timestamp (ADR-0064 §2). Advance the base instead.
  if (current === content) return { kind: "fresh-equals-disk" };
  // The file is exactly the last generated text: nobody edited it, so there is nothing to
  // merge. Write the fresh bytes directly; `git merge-file` (two temp files and a process)
  // runs only for a real hand edit.
  if (current === snapshot.text) return { kind: "snapshot-pristine-overwrite" };
  return { kind: "snapshot-merge-required", snapshotText: snapshot.text };
}

/**
 * What `decideAndWrite` WOULD do, touching nothing. Backs `meta gen --dry-run`.
 *
 * Exact for every outcome the hash manifest decides, because those are pure
 * comparisons — `classifyWrite` above is the single source for which one applies.
 * Deliberately COARSE in one place: with a snapshot body present the result depends
 * on whether `git merge-file` comes back clean or conflicted, which cannot be known
 * without performing the merge — so that case reports `overwrite`, meaning "this
 * file will be rewritten", which is true either way.
 *
 * The reason this exists as its own function rather than a flag on
 * `decideAndWrite`: a preview must be incapable of writing, and the cheapest way to
 * guarantee that is to give it no write in its body at all — mapping a `WriteCase`
 * to a status touches no file and no manifest.
 */
export function previewWriteStatus(
  path: string,
  content: string,
  optsOrStrategy: DecideAndWriteOpts | MergeStrategy = {},
): WriteStatus {
  const kase = classifyWrite(path, content, normalizeOpts(optsOrStrategy));
  switch (kase.kind) {
    case "new":
      return "new";
    case "skip":
      return "skipped";
    case "no-snapshot-fresh-unchanged":
    case "no-snapshot-unchanged":
    case "snapshot-unchanged":
    case "fresh-equals-disk":
      return "unchanged";
    case "no-snapshot-fresh-overwrite":
    case "no-snapshot-pristine-overwrite":
    case "snapshot-pristine-overwrite":
    case "hand-edit-overwrite":
      return "overwrite";
    case "no-snapshot-refused":
      return "refused";
    case "no-snapshot-adopt":
      return "adopted";
    case "snapshot-merge-required":
      return "overwrite";
  }
}

/**
 * The main entry point. Backward-compatible with the rc.11 signature: passing
 * a `MergeStrategy` string as the third argument continues to work; passing
 * an options object opts into three-way merge.
 */
export function decideAndWrite(
  path: string,
  content: string,
  optsOrStrategy: DecideAndWriteOpts | MergeStrategy = {},
): WriteResult {
  const opts = normalizeOpts(optsOrStrategy);
  const genStateDir = resolveGenStateDir(opts);
  const relPath = opts.outputRelPath ?? defaultOutputRelPath(path);
  const kase = classifyWrite(path, content, opts);

  switch (kase.kind) {
    case "new":
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, content);
      advanceSnapshot(genStateDir, relPath, content);
      return { path, status: "new" };

    case "skip":
      return { path, status: "skipped" };

    case "no-snapshot-fresh-unchanged":
    case "no-snapshot-unchanged":
      // Identical content needs no write, in either mode — just seed/advance the
      // snapshot so the file is recognisable as ours next time.
      advanceSnapshot(genStateDir, relPath, content);
      return { path, status: "unchanged" };

    case "no-snapshot-fresh-overwrite":
    case "no-snapshot-pristine-overwrite":
    case "snapshot-pristine-overwrite":
      writeFileSync(path, content);
      advanceSnapshot(genStateDir, relPath, content);
      return { path, status: "overwrite" };

    case "hand-edit-overwrite":
      writeFileSync(path, content);
      advanceSnapshot(genStateDir, relPath, content);
      return { path, status: "overwrite", discardedEdit: true };

    case "no-snapshot-refused":
      // Deliberately does NOT advance the snapshot or the hash: a refusal that
      // records the current content would make the file look pristine next run and
      // turn this into a silent overwrite one run later.
      return {
        path,
        status: "refused",
        // The hint states WHAT HAPPENED, per file, and points at the recovery rather
        // than restating it. The two remedies it used to name were both WRONG for the
        // generator with the most at stake: `requirementTests()` emits a stub whose
        // entire value is the body you write over it, and whose own header says "do not
        // rename the test — the name is the link", so "move your edits into a
        // non-generated file" asks for something the artifact forbids, and
        // "--baseline=fresh to discard them" discards the only content the file has.
        // The sequence that actually keeps an edit is three commands long and identical
        // for every file in the run, so `runner.ts` prints it once; a doc pointer is
        // what a direct `decideAndWrite` caller (a public export — no runner involved)
        // gets instead, and it is never wrong.
        conflictHint: kase.hasRecord
          ? "this file has been edited since it was generated, and there is no " +
            ".gen-state snapshot body on this machine to merge against — it was NOT " +
            "overwritten, and your version is intact on disk. Recovery: " +
            "docs/features/own-your-codegen.md."
          : "no record of generating this file, and its content differs from fresh " +
            "output — it was NOT overwritten. Move it aside, or re-run with " +
            "--baseline=fresh to overwrite it and adopt fresh output as the baseline.",
      };

    case "no-snapshot-adopt":
      // Record what is ON DISK — deliberately `kase.currentText`, never `content`.
      // Recording fresh output would claim we wrote a file we did not, and the next
      // run would then read the adopter's file as edited-since-generated and refuse
      // all over again, which is the loop this mode exists to end.
      advanceSnapshot(genStateDir, relPath, kase.currentText);
      return { path, status: "adopted" };

    case "snapshot-unchanged":
      return { path, status: "unchanged" };

    case "fresh-equals-disk":
      advanceSnapshot(genStateDir, relPath, content);
      return { path, status: "unchanged" };

    case "snapshot-merge-required": {
      // The two merge inputs are temporaries, always removed, whatever the merge does.
      const temps: string[] = [];
      let outcome: MergeOutcome;
      try {
        const baseTmp = writeTmpfile(kase.snapshotText);
        temps.push(baseTmp);
        const freshTmp = writeTmpfile(content);
        temps.push(freshTmp);
        outcome = runGitMergeFile(path, baseTmp, freshTmp);
      } finally {
        for (const t of temps) rmSync(t, { force: true });
      }

      if (outcome.exitCode === 0) {
        // Clean merge — advance the canonical snapshot to fresh.
        advanceSnapshot(genStateDir, relPath, content);
        // Distinguish "user had no changes vs canonical" from "merge integrated
        // edits". The fresh-equals-snapshot case is `snapshot-unchanged` above —
        // so if the merged result equals fresh we report a plain overwrite,
        // otherwise it's a merge that pulled in user edits.
        return {
          path,
          status: outcome.mergedContent === content ? "overwrite" : "merged",
        };
      }

      // Conflict — do NOT advance the snapshot. The output now contains diff3
      // markers from git merge-file.
      return {
        path,
        status: "conflict",
        conflictHint:
          "merge conflict — resolve `<<<<<<<` markers and re-run `meta gen` to " +
          "advance the canonical state.",
      };
    }
  }
}
